INSERT [quotation].[ProposalShare] ([Id], [QuotationId], [BusinessId], [ShareToken], [SnapshotHtml], [CustomerEmail], [ExpiresAtUtc], [CreatedAtUtc], [CreatedByUserId], [IsActive]) VALUES (1, 1004, 1, N'qH3yw6-p93apPcM6Q-U0REJ1WbYpcOxN1Xnr_GIqz2I', N'<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Proposal — QUO-1-00001</title>
    <style>
        @import url(''https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Manrope:wght@600;700;800&display=swap'');

        :root {
            --bg: #F7FAFC;
            --bg2: #EEF4F8;
            --text: #0B1B28;
            --muted: #5E7385;
            --blue: #0D5EA6;
            --blue-dark: #0B4E89;
            --cyan: #57B8E8;
            --green: #129867;
            --line: rgba(13,94,166,.10);
            --shadow: 0 22px 56px rgba(13,94,166,.10);
        }

        @page { size: A4; margin: 14mm; }

        * { box-sizing: border-box; }

        body {
            margin: 0;
            font-family: Inter, -apple-system, BlinkMacSystemFont, ''Segoe UI'', sans-serif;
            color: var(--text);
            background:
                radial-gradient(circle at top left, rgba(13,94,166,.08), transparent 28%),
                radial-gradient(circle at top right, rgba(87,184,232,.06), transparent 24%),
                linear-gradient(180deg, #FBFDFF 0%, var(--bg2) 48%, var(--bg) 100%);
            -webkit-font-smoothing: antialiased;
            text-rendering: optimizeLegibility;
            line-height: 1.6;
        }

        h1, h2, h3, h4 {
            font-family: Manrope, Inter, sans-serif;
            letter-spacing: -.03em;
            margin: 0;
        }

        .page-wrap {
            max-width: 1180px;
            margin: 0 auto;
            padding: 24px;
        }

        .sheet {
            background: linear-gradient(180deg, rgba(255,255,255,.99) 0%, rgba(245,249,253,.98) 100%);
            border: 1px solid var(--line);
            box-shadow: var(--shadow);
            border-radius: 32px;
            overflow: hidden;
        }

        /* Hero */
        .hero {
            position: relative;
            overflow: hidden;
            padding: 42px;
            background:
                radial-gradient(circle at top left, rgba(87,184,232,.12), transparent 28%),
                linear-gradient(180deg, rgba(13,94,166,.08) 0%, rgba(255,255,255,.02) 100%);
            border-bottom: 1px solid rgba(13,94,166,.08);
        }
        .hero::after {
            content: "";
            position: absolute;
            right: -100px;
            top: -120px;
            width: 320px;
            height: 320px;
            border-radius: 999px;
            background: rgba(13,94,166,.08);
        }
        .hero-grid {
            display: grid;
            grid-template-columns: 1fr 360px;
            gap: 40px;
            align-items: start;
            position: relative;
            z-index: 1;
        }

        .hero-logos {
            display: flex;
            align-items: center;
            gap: 20px;
            flex-wrap: wrap;
            margin-bottom: 18px;
        }
        .hero-logos img {
            max-height: 68px;
            width: auto;
            object-fit: contain;
        }

        .eyebrow {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            padding: 10px 14px;
            border-radius: 999px;
            border: 1px solid rgba(13,94,166,.10);
            background: rgba(255,255,255,.88);
            color: var(--blue-dark);
            font-size: 12px;
            font-weight: 700;
            letter-spacing: .16em;
            text-transform: uppercase;
            box-shadow: 0 10px 22px rgba(13,94,166,.06);
        }
        .dot {
            width: 10px;
            height: 10px;
            border-radius: 999px;
            background: var(--cyan);
            box-shadow: 0 0 0 8px rgba(87,184,232,.10);
        }

        .hero h1 {
            margin-top: 28px;
            font-size: 42px;
            font-weight: 800;
            line-height: 1.15;
            color: #0B1B28;
        }
        .hero .subtitle {
            margin-top: 18px;
            font-size: 17px;
            line-height: 1.7;
            color: var(--muted);
            max-width: 600px;
        }

        /* Meta card */
        .meta-card {
            background: linear-gradient(180deg, rgba(255,255,255,.99) 0%, rgba(244,249,253,.98) 100%);
            border: 1px solid rgba(13,94,166,.08);
            border-radius: 26px;
            box-shadow: 0 14px 30px rgba(13,94,166,.06);
            padding: 28px;
        }
        .meta-card .label {
            font-size: 11px;
            font-weight: 700;
            letter-spacing: .12em;
            text-transform: uppercase;
            color: var(--blue-dark);
        }
        .meta-card .value {
            margin-top: 6px;
            font-size: 16px;
            font-weight: 700;
            color: #0B1B28;
        }
        .meta-card .value-sm {
            margin-top: 4px;
            font-size: 14px;
            color: var(--muted);
        }
        .meta-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 18px;
            margin-top: 18px;
        }
        .meta-row {
            margin-top: 18px;
        }
        .meta-logo {
            margin-top: 18px;
            padding-top: 18px;
            border-top: 1px solid rgba(13,94,166,.08);
        }
        .meta-logo img {
            max-height: 40px;
            width: auto;
            object-fit: contain;
        }

        /* Main content */
        .main {
            padding: 32px 42px 42px;
        }

        /* Section cards */
        .section-card {
            background: linear-gradient(180deg, rgba(255,255,255,.99) 0%, rgba(244,249,253,.98) 100%);
            border: 1px solid rgba(13,94,166,.08);
            border-radius: 26px;
            box-shadow: 0 14px 30px rgba(13,94,166,.06);
            padding: 32px;
            margin-top: 24px;
        }
        .section-card:first-child { margin-top: 0; }

        .label {
            font-size: 12px;
            font-weight: 700;
            letter-spacing: .12em;
            text-transform: uppercase;
            color: var(--blue-dark);
        }

        .section-title {
            margin-top: 12px;
            font-size: 28px;
            font-weight: 800;
            color: #0B1B28;
        }

        .section-desc {
            margin-top: 14px;
            font-size: 15px;
            line-height: 1.8;
            color: var(--muted);
        }

        /* Grid layouts */
        .grid-2 {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 24px;
        }

        /* Tables */
        .table-wrap { overflow-x: auto; margin-top: 24px; }
        table {
            width: 100%;
            border-collapse: separate;
            border-spacing: 0;
            border-radius: 18px;
            overflow: hidden;
        }
        thead th {
            background: #F4FAFE;
            color: #395367;
            font-size: 11px;
            font-weight: 800;
            letter-spacing: .08em;
            text-transform: uppercase;
            border-bottom: 1px solid rgba(13,94,166,.08);
            padding: 14px 16px;
            text-align: left;
        }
        td {
            padding: 16px;
            text-align: left;
            border-right: 1px solid rgba(13,94,166,.06);
            vertical-align: top;
        }
        td:last-child { border-right: 0; }
        tbody tr { background: rgba(255,255,255,.86); }
        tbody tr + tr td { border-top: 1px solid rgba(13,94,166,.06); }
        .money { font-weight: 800; color: #162A3D; white-space: nowrap; }
        .line-title { font-weight: 700; color: #0B1B28; }
        .line-title a { color: var(--blue); text-decoration: none; font-weight: 700; }
        .line-title a:hover { text-decoration: underline; }
        .line-desc { margin-top: 6px; font-size: 13px; color: var(--muted); line-height: 1.6; }
        .line-subtitle { margin-top: 4px; font-size: 13px; color: var(--muted); line-height: 1.5; }

        /* Narrative section */
        .narrative-body { margin-top: 18px; font-size: 15px; line-height: 1.8; color: var(--muted); }

        /* Total box */
        .total-box {
            background: linear-gradient(180deg, rgba(13,94,166,.08) 0%, rgba(13,94,166,.04) 100%);
            border: 1px solid rgba(13,94,166,.10);
            border-radius: 22px;
            padding: 24px;
            margin-top: 24px;
            max-width: 420px;
            margin-left: auto;
        }
        .section-total-box {
            background: linear-gradient(180deg, rgba(13,94,166,.08) 0%, rgba(13,94,166,.04) 100%);
            border: 1px solid rgba(13,94,166,.10);
            border-radius: 22px;
            padding: 24px;
            margin-top: 24px;
            max-width: 420px;
            margin-left: auto;
        }
        .total-row {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 10px 0;
        }
        .total-row + .total-row { border-top: 1px solid rgba(13,94,166,.10); }
        .total-label {
            font-size: 12px;
            font-weight: 700;
            letter-spacing: .1em;
            text-transform: uppercase;
            color: var(--muted);
        }
        .total-value {
            font-size: 20px;
            font-weight: 800;
            color: #0B1B28;
        }

        /* Notes list */
        .notes-list {
            margin: 16px 0 0 0;
            padding-left: 20px;
            list-style: disc;
        }
        .notes-list li {
            margin-top: 8px;
            font-size: 14px;
            line-height: 1.7;
            color: #3D4F5F;
        }

        /* Footer / signature */
        .footer-line {
            height: 1px;
            background: linear-gradient(90deg, rgba(13,94,166,0), rgba(13,94,166,.24), rgba(13,94,166,0));
